package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Gives the selected people the grade in list order (the order they were added), each as the
 *  person form would (see {@link ApplyPerson}: from the from-date, blank the sheet's today) and
 *  recorded as it would record it (its PERSON_EDITED line, then the rollup lines it moved). A
 *  selected id not on the sheet is skipped. */
public class BulkGradePeople {
    public void grade(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, @Val BulkGradeRequest request,
            PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, Audit audit, Out<BulkGradeResult> result)
            throws PersonConflictException {
        String id = sheetId.trim();
        String user = by == null ? "" : by;
        Set<Long> selected = new HashSet<>(request.personIds());
        LocalDate today = sheets.today(id);
        int graded = 0;
        Rollup before = Rollup.of(id, people, claims, rates, sheets, settings);
        for (Person listed : people.list(id)) {
            if (!selected.contains(listed.getId())) continue;
            Person person = people.find(id, listed.getId());
            // As the form: no from-date and the grade already in force gives none.
            if (request.from() != null || !request.grade().equals(person.getGrade())) {
                person.giveGrade(request.grade(), request.from() != null ? request.from() : today.toString(), today);
            }
            if (!people.update(person)) {
                throw new PersonConflictException(person.getId());
            }
            if (person.getRecorded() != null) {
                people.saveGrade(person, person.getRecorded(), user);
            }
            graded++;
            audit.record("PERSON_EDITED sheet=" + id + " by=" + user + " name=" + person.getName()
                    + " grade=" + person.getGrade());
            Rollup after = Rollup.of(id, people, claims, rates, sheets, settings);
            for (String line : after.changesSince(before, id, user)) {
                audit.record(line);
            }
            before = after;
        }
        result.set(new BulkGradeResult(graded));
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { claimsKey } from '../claims/api';
import { GRADES, bulkGradePeople, peopleKey } from './api';

/** A grade, a from-date (blank: the sheet's today) and a button that gives the selected people that
 *  grade together, and how many it changed. The count is cleared while it runs; the selection is
 *  cleared once it is done. A refusal shows until the form is changed or submitted again. */
export function BulkGrade({ sheetId, user, selected, onDone }: {
  sheetId: string; user: string; selected: number[]; onDone: () => void;
}) {
  const queryClient = useQueryClient();
  const runOnce = useSubmitOnce();
  const [grade, setGrade] = useState<string>('A');
  const [from, setFrom] = useState('');
  const bulk = useMutation({
    mutationFn: (v: { ids: number[]; grade: string; from: string }) => bulkGradePeople(sheetId, user, v.ids, v.grade, v.from),
    onSuccess: () => {
      onDone();
      return Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });

  return (
    <div>
      <label>
        Grade{' '}
        <select data-testid="bulk-grade" value={grade} onChange={(e) => { setGrade(e.target.value); bulk.reset(); }}>
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        from{' '}
        <input type="date" data-testid="bulk-grade-from" value={from} onChange={(e) => { setFrom(e.target.value); bulk.reset(); }} />
      </label>{' '}
      <button type="button" data-testid="bulk-grade-apply" disabled={bulk.isPending}
        onClick={() => {
          const v = { ids: [...selected], grade, from };
          runOnce(() => {
            bulk.reset();
            return bulk.mutateAsync(v);
          });
        }}>
        Grade selected ({selected.length})
      </button>
      {bulk.isSuccess && (
        <>
          {' '}Changed <span data-testid="bulk-graded">{bulk.data.graded}</span>
        </>
      )}
      {bulk.isError && <span data-testid="person-error">The selected people could not be graded: select someone, and a from-date (if any) must be a date.</span>}
    </div>
  );
}
